<template><main class="login"><el-card><h1>忆路银龄</h1><p>数字金融陪伴平台</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" placeholder="用户名"/></el-form-item><el-form-item><el-input v-model="form.password" type="password" placeholder="密码" show-password/></el-form-item><el-button type="primary" native-type="submit" :loading="loading" style="width:100%">登录</el-button></el-form></el-card></main></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {useAuthStore} from '../stores/auth';const router=useRouter(),store=useAuthStore(),loading=ref(false),form=reactive({username:'admin',password:'123456'});async function submit(){loading.value=true;try{await store.signIn(form);router.push('/dashboard')}catch(e){ElMessage.error('登录失败，请检查账号密码')}finally{loading.value=false}}</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:#f4f7fb}.el-card{width:360px;padding:20px}h1{margin:0;color:#1769aa}p{color:#6b7280}</style>
